import Box from '@mui/material/Box';
import { RowCell, ROW_COUNT, SeatState, couchIds, getCouchState, getRowLayout, getSeatState, seatId } from '../../lib/seats';

const SEAT_SIZE = 34;
const GAP = 3;
const COUCH_SIZE = SEAT_SIZE * 2 + GAP;
const LEFT_BLOCK_WIDTH = SEAT_SIZE * 4 + GAP * 3;
const AISLE_WIDTH = SEAT_SIZE * 2;
const LABEL_WIDTH = 28;

const STATE_COLORS: Record<SeatState, string> = {
  available: '#2E7D32',
  selected: '#F9A825',
  unavailable: '#C62828',
  accessible: '#1565C0',
};

interface AuditoriumProps {
  occupiedSeats: Set<string>;
  selectedSeats: Set<string>;
  onSeatClick: (id: string) => void;
  onCouchClick: (ids: [string, string]) => void;
}

export function Auditorium({ occupiedSeats, selectedSeats, onSeatClick, onCouchClick }: AuditoriumProps) {
  const rows = Array.from({ length: ROW_COUNT }, (_, i) => i + 1);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <Box
        data-testid="screen-indicator"
        sx={{
          width: '60%',
          maxWidth: 640,
          height: 36,
          mb: 3,
          borderRadius: '50% / 100%',
          bgcolor: '#9e9e9e',
          color: '#fff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          letterSpacing: 4,
          fontWeight: 600,
          fontSize: 14,
        }}
      >
        SCREEN
      </Box>

      <Box data-testid="seat-map" sx={{ display: 'flex', flexDirection: 'column', gap: `${GAP}px` }}>
        {rows.map((row) => (
          <Row
            key={row}
            row={row}
            occupiedSeats={occupiedSeats}
            selectedSeats={selectedSeats}
            onSeatClick={onSeatClick}
            onCouchClick={onCouchClick}
          />
        ))}
      </Box>
    </Box>
  );
}

interface RowProps {
  row: number;
  occupiedSeats: Set<string>;
  selectedSeats: Set<string>;
  onSeatClick: (id: string) => void;
  onCouchClick: (ids: [string, string]) => void;
}

function Row({ row, occupiedSeats, selectedSeats, onSeatClick, onCouchClick }: RowProps) {
  const layout = getRowLayout(row);

  return (
    <Box data-testid="seat-row" data-row={row} sx={{ display: 'flex', alignItems: 'center', gap: `${GAP}px` }}>
      <RowLabel row={row} side="left" />
      <Block
        cells={layout.leftBlock}
        row={row}
        occupiedSeats={occupiedSeats}
        selectedSeats={selectedSeats}
        onSeatClick={onSeatClick}
        onCouchClick={onCouchClick}
        emptyWidth={LEFT_BLOCK_WIDTH}
      />
      <Aisle row={row} />
      <Block
        cells={layout.middleBlock}
        row={row}
        occupiedSeats={occupiedSeats}
        selectedSeats={selectedSeats}
        onSeatClick={onSeatClick}
        onCouchClick={onCouchClick}
        emptyWidth={0}
      />
      <Aisle row={row} />
      <Block
        cells={layout.rightBlock}
        row={row}
        occupiedSeats={occupiedSeats}
        selectedSeats={selectedSeats}
        onSeatClick={onSeatClick}
        onCouchClick={onCouchClick}
        emptyWidth={0}
      />
      <RowLabel row={row} side="right" />
    </Box>
  );
}

interface BlockProps {
  cells: RowCell[];
  row: number;
  occupiedSeats: Set<string>;
  selectedSeats: Set<string>;
  onSeatClick: (id: string) => void;
  onCouchClick: (ids: [string, string]) => void;
  emptyWidth: number;
}

function Block({ cells, row, occupiedSeats, selectedSeats, onSeatClick, onCouchClick, emptyWidth }: BlockProps) {
  if (cells.length === 0) {
    return <Box sx={{ width: emptyWidth, height: SEAT_SIZE, flexShrink: 0 }} />;
  }
  return (
    <Box sx={{ display: 'flex', gap: `${GAP}px` }}>
      {cells.map((cell) =>
        cell.kind === 'couch' ? (
          <Couch
            key={`${row}-${cell.columnStart}`}
            row={row}
            columnStart={cell.columnStart}
            columnEnd={cell.columnEnd}
            occupiedSeats={occupiedSeats}
            selectedSeats={selectedSeats}
            onCouchClick={onCouchClick}
          />
        ) : (
          <Seat
            key={`${row}-${cell.column}`}
            row={row}
            column={cell.column}
            occupiedSeats={occupiedSeats}
            selectedSeats={selectedSeats}
            onSeatClick={onSeatClick}
          />
        ),
      )}
    </Box>
  );
}

interface SeatProps {
  row: number;
  column: number;
  occupiedSeats: Set<string>;
  selectedSeats: Set<string>;
  onSeatClick: (id: string) => void;
}

function Seat({ row, column, occupiedSeats, selectedSeats, onSeatClick }: SeatProps) {
  const id = seatId(row, column);
  const state = getSeatState(id, row, column, occupiedSeats, selectedSeats);

  return (
    <button
      type="button"
      data-testid="seat"
      data-row={row}
      data-column={column}
      data-state={state}
      onClick={() => {
        if (state !== 'unavailable') onSeatClick(id);
      }}
      style={{
        width: SEAT_SIZE,
        height: SEAT_SIZE,
        flexShrink: 0,
        border: 'none',
        borderRadius: 4,
        backgroundColor: STATE_COLORS[state],
        color: '#fff',
        fontSize: 11,
        cursor: state === 'unavailable' ? 'default' : 'pointer',
        padding: 0,
      }}
    >
      {column}
    </button>
  );
}

interface CouchProps {
  row: number;
  columnStart: number;
  columnEnd: number;
  occupiedSeats: Set<string>;
  selectedSeats: Set<string>;
  onCouchClick: (ids: [string, string]) => void;
}

function Couch({ row, columnStart, columnEnd, occupiedSeats, selectedSeats, onCouchClick }: CouchProps) {
  const ids = couchIds(row, columnStart);
  const state = getCouchState(ids, occupiedSeats, selectedSeats);

  return (
    <button
      type="button"
      data-testid="couch"
      data-row={row}
      data-column-start={columnStart}
      data-column-end={columnEnd}
      data-state={state}
      onClick={() => {
        if (state !== 'unavailable') onCouchClick(ids);
      }}
      style={{
        width: COUCH_SIZE,
        height: SEAT_SIZE,
        flexShrink: 0,
        border: 'none',
        borderRadius: 4,
        backgroundColor: STATE_COLORS[state],
        color: '#fff',
        fontSize: 11,
        cursor: state === 'unavailable' ? 'default' : 'pointer',
        padding: 0,
      }}
    >
      {columnStart}-{columnEnd}
    </button>
  );
}

function RowLabel({ row, side }: { row: number; side: 'left' | 'right' }) {
  return (
    <Box
      data-testid={side === 'left' ? 'row-label-left' : 'row-label-right'}
      data-row={row}
      sx={{ width: LABEL_WIDTH, textAlign: 'center', flexShrink: 0, fontSize: 13, fontWeight: 600 }}
    >
      {row}
    </Box>
  );
}

function Aisle({ row }: { row: number }) {
  return <Box data-testid="aisle" data-row={row} sx={{ width: AISLE_WIDTH, height: SEAT_SIZE, flexShrink: 0 }} />;
}

import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { SeatState } from '../../lib/seats';

const ITEMS: Array<{ state: SeatState; label: string; color: string }> = [
  { state: 'available', label: 'Available', color: '#2E7D32' },
  { state: 'selected', label: 'Selected', color: '#F9A825' },
  { state: 'unavailable', label: 'Unavailable', color: '#C62828' },
  { state: 'accessible', label: 'Accessible', color: '#1565C0' },
];

export function Legend() {
  return (
    <Box data-testid="legend" sx={{ display: 'flex', gap: 3, justifyContent: 'center', mt: 3 }}>
      {ITEMS.map((item) => (
        <Box key={item.state} data-testid="legend-item" data-state={item.state} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Box sx={{ width: 16, height: 16, borderRadius: '4px', bgcolor: item.color }} />
          <Typography variant="body2">{item.label}</Typography>
        </Box>
      ))}
    </Box>
  );
}

import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useBooking } from '../../context/BookingContext';
import { useToast } from '../../context/ToastContext';
import { getMovie, getScreening } from '../../lib/api';
import { createBooking } from '../../lib/booking';
import { formatShowDate } from '../../lib/dates';
import { MAX_SEATS_PER_BOOKING, toggleCouchSelection, toggleSeatSelection } from '../../lib/seats';
import { Movie, Screening } from '../../lib/types';
import { Auditorium } from './Auditorium';
import { Legend } from './Legend';
import { SelectedSeatsPanel } from './SelectedSeatsPanel';

export function SeatMap() {
  const { id } = useParams<{ id: string }>();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, setBooking, updateBooking, clearBooking } = useBooking();
  const { showToast } = useToast();

  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);
  const initializedForRef = useRef<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    setScreening(null);
    setMovie(null);
    getScreening(screeningId)
      .then((loadedScreening) =>
        getMovie(loadedScreening.movieId).then((loadedMovie) => {
          if (cancelled) return;
          setScreening(loadedScreening);
          setMovie(loadedMovie);
        }),
      )
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
  }, [screeningId, navigate]);

  useEffect(() => {
    if (!screening) return;
    if (initializedForRef.current === screening.id) return;
    initializedForRef.current = screening.id;
    const matches = booking && !booking.paid && booking.screeningId === screening.id;
    if (!matches) {
      setBooking(createBooking(screening.id));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screening]);

  const occupiedSeats = useMemo(() => new Set(screening?.occupiedSeats ?? []), [screening]);
  const selectedSeats = useMemo(
    () => new Set(booking && booking.screeningId === screeningId ? booking.seats : []),
    [booking, screeningId],
  );

  const ready = screening && movie && booking && booking.screeningId === screeningId && initializedForRef.current === screening.id;

  if (!ready || !screening || !movie) {
    return null;
  }

  const handleSeatClick = (seatId: string) => {
    const result = toggleSeatSelection(booking!.seats, seatId);
    if (result === null) {
      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
      return;
    }
    updateBooking((b) => ({ ...b, seats: result }));
  };

  const handleCouchClick = (ids: [string, string]) => {
    const result = toggleCouchSelection(booking!.seats, ids);
    if (result === null) {
      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
      return;
    }
    updateBooking((b) => ({ ...b, seats: result }));
  };

  const handleCancel = () => {
    clearBooking();
    navigate('/');
  };

  const handleContinue = () => {
    if (booking!.seats.length === 0) return;
    navigate(`/screenings/${screening.id}/summary`);
  };

  return (
    <Box sx={{ maxWidth: 1100, mx: 'auto', p: 3 }}>
      <Typography data-testid="seat-map-title" variant="h4" align="center" sx={{ mb: 1 }}>
        Choose your seats
      </Typography>
      <Typography data-testid="seat-map-subtitle" align="center" sx={{ mb: 2 }}>
        Show Date: {formatShowDate(screening.date, screening.time)}
      </Typography>
      <Typography data-testid="seat-limit-info" align="center" sx={{ mb: 3 }}>
        You can reserve up to {MAX_SEATS_PER_BOOKING} seats per reservation
      </Typography>

      <Auditorium
        occupiedSeats={occupiedSeats}
        selectedSeats={selectedSeats}
        onSeatClick={handleSeatClick}
        onCouchClick={handleCouchClick}
      />

      <Legend />

      <SelectedSeatsPanel selectedIds={booking!.seats} />

      <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2, mt: 3 }}>
        <Button data-testid="cancel-button" variant="outlined" onClick={handleCancel}>
          Cancel
        </Button>
        <Button
          data-testid="continue-button"
          variant="contained"
          disabled={booking!.seats.length === 0}
          onClick={handleContinue}
        >
          Continue
        </Button>
      </Box>
    </Box>
  );
}

