import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useBooking } from '../../context/BookingContext';
import { getMovie, getScreening } from '../../lib/api';
import { buildBookingItems, formatPrice } from '../../lib/seats';
import { Movie, Screening } from '../../lib/types';
import { useUnpaidBookingGuard } from '../../routes/useBookingGuard';

export function Summary() {
  const { id } = useParams<{ id: string }>();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, updateBooking } = useBooking();

  useUnpaidBookingGuard(screeningId);

  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);

  useEffect(() => {
    let cancelled = false;
    getScreening(screeningId)
      .then((loadedScreening) =>
        getMovie(loadedScreening.movieId).then((loadedMovie) => {
          if (cancelled) return;
          setScreening(loadedScreening);
          setMovie(loadedMovie);
        }),
      )
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
  }, [screeningId, navigate]);

  const items = useMemo(() => buildBookingItems(booking?.seats ?? []), [booking]);
  const total = items.reduce((sum, item) => sum + item.price, 0);

  if (!screening || !movie || !booking) {
    return null;
  }

  const handleRemove = (ids: string[]) => {
    const nextSeats = booking.seats.filter((seatId) => !ids.includes(seatId));
    updateBooking((b) => ({ ...b, seats: nextSeats }));
    if (nextSeats.length === 0) {
      navigate(`/screenings/${screeningId}/seats`);
    }
  };

  return (
    <Box sx={{ maxWidth: 800, mx: 'auto', p: 3 }}>
      <Typography data-testid="summary-title" variant="h4" sx={{ mb: 3 }}>
        Your tickets
      </Typography>

      <Box data-testid="summary-list" sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        {items.map((item) => (
          <Box
            key={item.ids.join('-')}
            data-testid="summary-item"
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              border: '1px solid #ccc',
              borderRadius: 1,
              p: 2,
            }}
          >
            <Box>
              <Typography data-testid="summary-item-title">{movie.title}</Typography>
              <Typography data-testid="summary-item-datetime">
                {screening.date} {screening.time}
              </Typography>
              <Typography data-testid="summary-item-row">{item.row}</Typography>
              <Typography data-testid="summary-item-seat">
                {item.kind === 'couch' ? `Couch ${item.columnStart}-${item.columnEnd}` : `${item.column}`}
              </Typography>
              <Typography data-testid="summary-item-price">{formatPrice(item.price)}</Typography>
            </Box>
            <Button data-testid="summary-item-remove-button" onClick={() => handleRemove(item.ids)}>
              Remove
            </Button>
          </Box>
        ))}
      </Box>

      <Typography data-testid="summary-total" sx={{ mt: 2 }}>
        Total: {formatPrice(total)}
      </Typography>

      <Box sx={{ display: 'flex', gap: 2, mt: 3 }}>
        <Button data-testid="back-button" variant="outlined" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
          Back
        </Button>
        <Button
          data-testid="confirm-button"
          variant="contained"
          onClick={() => navigate(`/screenings/${screeningId}/checkout`)}
        >
          Confirm
        </Button>
      </Box>
    </Box>
  );
}

import { CheckoutForm } from './booking';

export type CheckoutField = 'firstName' | 'lastName' | 'email' | 'confirmEmail' | 'phone' | 'terms';

export type CheckoutErrors = Partial<Record<CheckoutField, string>>;

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_REGEX = /^\d{9}$/;

export function validateCheckoutForm(form: CheckoutForm): CheckoutErrors {
  const errors: CheckoutErrors = {};

  if (form.firstName.length === 0) {
    errors.firstName = 'First name is required';
  } else if (form.firstName.length < 2) {
    errors.firstName = 'First name must be at least 2 characters';
  }

  if (form.lastName.length === 0) {
    errors.lastName = 'Last name is required';
  } else if (form.lastName.length < 2) {
    errors.lastName = 'Last name must be at least 2 characters';
  }

  if (form.email.length === 0) {
    errors.email = 'Email is required';
  } else if (!EMAIL_REGEX.test(form.email)) {
    errors.email = 'Enter a valid email address';
  }

  if (form.confirmEmail.length === 0) {
    errors.confirmEmail = 'Confirm email is required';
  } else if (form.confirmEmail !== form.email) {
    errors.confirmEmail = 'Email addresses do not match';
  }

  if (form.phone.length > 0 && !PHONE_REGEX.test(form.phone)) {
    errors.phone = 'Phone number must be exactly 9 digits';
  }

  if (!form.terms) {
    errors.terms = 'You must accept the terms and conditions';
  }

  return errors;
}

import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useBooking } from '../../context/BookingContext';
import { useToast } from '../../context/ToastContext';
import { createReservation } from '../../lib/api';
import { CheckoutForm } from '../../lib/booking';
import { CheckoutField, validateCheckoutForm } from '../../lib/checkoutValidation';
import { buildBookingItems, formatPrice } from '../../lib/seats';
import { useUnpaidBookingGuard } from '../../routes/useBookingGuard';

const INITIAL_TOUCHED: Record<CheckoutField, boolean> = {
  firstName: false,
  lastName: false,
  email: false,
  confirmEmail: false,
  phone: false,
  terms: false,
};

export function Checkout() {
  const { id } = useParams<{ id: string }>();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, updateBooking } = useBooking();
  const { showToast } = useToast();

  useUnpaidBookingGuard(screeningId);

  const [touched, setTouched] = useState<Record<CheckoutField, boolean>>(INITIAL_TOUCHED);
  const [submitting, setSubmitting] = useState(false);

  if (!booking) {
    return null;
  }

  const form = booking.form;
  const errors = validateCheckoutForm(form);
  const items = buildBookingItems(booking.seats);
  const total = items.reduce((sum, item) => sum + item.price, 0);

  function setField<K extends keyof CheckoutForm>(field: K, value: CheckoutForm[K]) {
    updateBooking((b) => ({ ...b, form: { ...b.form, [field]: value } }));
  }

  const markTouched = (field: CheckoutField) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const handlePay = async () => {
    if (Object.keys(errors).length > 0) {
      setTouched({
        firstName: true,
        lastName: true,
        email: true,
        confirmEmail: true,
        phone: true,
        terms: true,
      });
      showToast('The form contains errors');
      return;
    }

    setSubmitting(true);
    try {
      const seats = items.flatMap((item) => item.ids);
      await createReservation({
        screeningId: booking.screeningId,
        seats,
        customer: {
          firstName: form.firstName,
          lastName: form.lastName,
          email: form.email,
          phone: form.phone,
        },
        totalPrice: total,
      });
      updateBooking((b) => ({ ...b, paid: true, email: b.form.email }));
      navigate('/confirmation');
    } catch {
      showToast('Payment failed. Please try again.');
      setSubmitting(false);
    }
  };

  return (
    <Box sx={{ maxWidth: 560, mx: 'auto', p: 3 }}>
      <Typography data-testid="checkout-title" variant="h4" sx={{ mb: 3 }}>
        Your details
      </Typography>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
        <TextField
          data-testid="first-name-input"
          label="First name *"
          value={form.firstName}
          onChange={(e) => setField('firstName', e.target.value)}
          onBlur={() => markTouched('firstName')}
          error={touched.firstName && !!errors.firstName}
          slotProps={{ inputLabel: { 'data-testid': 'first-name-label' } }}
        />
        {touched.firstName && errors.firstName && (
          <Typography data-testid="first-name-error" color="error" variant="caption">
            {errors.firstName}
          </Typography>
        )}

        <TextField
          data-testid="last-name-input"
          label="Last name *"
          value={form.lastName}
          onChange={(e) => setField('lastName', e.target.value)}
          onBlur={() => markTouched('lastName')}
          error={touched.lastName && !!errors.lastName}
          slotProps={{ inputLabel: { 'data-testid': 'last-name-label' } }}
        />
        {touched.lastName && errors.lastName && (
          <Typography data-testid="last-name-error" color="error" variant="caption">
            {errors.lastName}
          </Typography>
        )}

        <TextField
          data-testid="email-input"
          label="Email *"
          value={form.email}
          onChange={(e) => setField('email', e.target.value)}
          onBlur={() => markTouched('email')}
          error={touched.email && !!errors.email}
          slotProps={{ inputLabel: { 'data-testid': 'email-label' } }}
        />
        {touched.email && errors.email && (
          <Typography data-testid="email-error" color="error" variant="caption">
            {errors.email}
          </Typography>
        )}

        <TextField
          data-testid="confirm-email-input"
          label="Confirm email *"
          value={form.confirmEmail}
          onChange={(e) => setField('confirmEmail', e.target.value)}
          onBlur={() => markTouched('confirmEmail')}
          error={touched.confirmEmail && !!errors.confirmEmail}
          slotProps={{ inputLabel: { 'data-testid': 'confirm-email-label' } }}
        />
        {touched.confirmEmail && errors.confirmEmail && (
          <Typography data-testid="confirm-email-error" color="error" variant="caption">
            {errors.confirmEmail}
          </Typography>
        )}

        <TextField
          data-testid="phone-input"
          label="Phone number"
          value={form.phone}
          onChange={(e) => setField('phone', e.target.value)}
          onBlur={() => markTouched('phone')}
          error={touched.phone && !!errors.phone}
          slotProps={{ inputLabel: { 'data-testid': 'phone-label' } }}
        />
        {touched.phone && errors.phone && (
          <Typography data-testid="phone-error" color="error" variant="caption">
            {errors.phone}
          </Typography>
        )}

        <FormControlLabel
          control={
            <Checkbox
              checked={form.terms}
              onChange={(e) => {
                setField('terms', e.target.checked);
                markTouched('terms');
              }}
              slotProps={{ input: { 'data-testid': 'terms-checkbox' } }}
            />
          }
          label={<Typography data-testid="terms-label">I accept the terms and conditions *</Typography>}
        />
        {touched.terms && errors.terms && (
          <Typography data-testid="terms-error" color="error" variant="caption">
            {errors.terms}
          </Typography>
        )}
      </Box>

      <Box sx={{ display: 'flex', gap: 2, mt: 3 }}>
        <Button
          data-testid="checkout-back-button"
          variant="outlined"
          onClick={() => navigate(`/screenings/${screeningId}/summary`)}
        >
          Back
        </Button>
        <Button data-testid="pay-button" variant="contained" disabled={submitting} onClick={handlePay}>
          {submitting ? 'Processing…' : `Pay ${formatPrice(total)}`}
        </Button>
      </Box>
    </Box>
  );
}

import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { useNavigate } from 'react-router-dom';
import { useBooking } from '../../context/BookingContext';
import { usePaidBookingGuard } from '../../routes/useBookingGuard';

export function Confirmation() {
  const { booking, clearBooking } = useBooking();
  const navigate = useNavigate();

  usePaidBookingGuard();

  if (!booking?.paid) {
    return null;
  }

  const handleContinue = () => {
    clearBooking();
    navigate('/');
  };

  return (
    <Box sx={{ maxWidth: 560, mx: 'auto', p: 3, textAlign: 'center' }}>
      <Typography data-testid="confirmation-heading" variant="h4" sx={{ mb: 2 }}>
        Payment successful
      </Typography>
      <Typography data-testid="confirmation-message" sx={{ mb: 3 }}>
        Your tickets will be sent shortly to {booking.email}
      </Typography>
      <Button data-testid="confirmation-continue-button" variant="contained" onClick={handleContinue}>
        Continue
      </Button>
    </Box>
  );
}

import { Navigate, Route, Routes } from 'react-router-dom';
import { Checkout } from '../pages/Checkout/Checkout';
import { Confirmation } from '../pages/Confirmation/Confirmation';
import { MovieList } from '../pages/MovieList/MovieList';
import { SeatMap } from '../pages/SeatMap/SeatMap';
import { Summary } from '../pages/Summary/Summary';

export function App() {
  return (
    <Routes>
      <Route path="/" element={<MovieList />} />
      <Route path="/screenings/:id/seats" element={<SeatMap />} />
      <Route path="/screenings/:id/summary" element={<Summary />} />
      <Route path="/screenings/:id/checkout" element={<Checkout />} />
      <Route path="/confirmation" element={<Confirmation />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default App;

