export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface ReservationInput {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface Reservation extends ReservationInput {
  id: number;
}

import { Movie, Reservation, ReservationInput, Screening } from './types';

const BASE_URL = 'http://localhost:3000';

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${BASE_URL}${path}`, init);
  if (!response.ok) {
    throw new Error(`Request to ${path} failed with status ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export function getMovies(): Promise<Movie[]> {
  return request<Movie[]>('/movies');
}

export function getMovie(id: number): Promise<Movie> {
  return request<Movie>(`/movies/${id}`);
}

export function getScreenings(filters: { date?: string; movieId?: number } = {}): Promise<Screening[]> {
  const params = new URLSearchParams();
  if (filters.date) params.set('date', filters.date);
  if (filters.movieId !== undefined) params.set('movieId', String(filters.movieId));
  const query = params.toString();
  return request<Screening[]>(`/screenings${query ? `?${query}` : ''}`);
}

export function getScreening(id: number): Promise<Screening> {
  return request<Screening>(`/screenings/${id}`);
}

export function createReservation(input: ReservationInput): Promise<Reservation> {
  return request<Reservation>('/reservations', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
}

import dayjs from 'dayjs';
import customParseFormat from 'dayjs/plugin/customParseFormat';

dayjs.extend(customParseFormat);

export const ISO_FORMAT = 'YYYY-MM-DD';

export function todayISO(): string {
  return dayjs().format(ISO_FORMAT);
}

export function isValidIsoDate(value: string): boolean {
  return dayjs(value, ISO_FORMAT, true).isValid();
}

export function isPastDate(iso: string): boolean {
  return dayjs(iso, ISO_FORMAT, true).isBefore(dayjs().startOf('day'));
}

/** A missing, invalid or past date selects today. */
export function resolveSelectedDate(dateParam: string | null): string {
  if (!dateParam || !isValidIsoDate(dateParam) || isPastDate(dateParam)) {
    return todayISO();
  }
  return dateParam;
}

export function nextDays(count: number): string[] {
  return Array.from({ length: count }, (_, i) => dayjs().add(i, 'day').format(ISO_FORMAT));
}

export function weekdayFull(iso: string): string {
  return dayjs(iso, ISO_FORMAT).format('dddd');
}

/** `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
export function formatShowDate(date: string, time: string): string {
  const d = dayjs(date, ISO_FORMAT);
  return `${d.format('dddd')} ${d.date()} ${d.format('MMM')} ${time}`;
}

export const ROW_COUNT = 15;
export const COLUMN_COUNT = 24;
export const COUCH_ROW = 15;
export const ACCESSIBLE_ROW = 1;
export const ACCESSIBLE_COLUMNS = [10, 11, 12, 13, 14, 15];
export const MAX_SEATS_PER_BOOKING = 10;
export const COUCH_PRICE = 89;

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export type SeatCell = { kind: 'seat'; column: number };
export type CouchCell = { kind: 'couch'; columnStart: number; columnEnd: number };
export type RowCell = SeatCell | CouchCell;

export interface RowLayout {
  row: number;
  leftBlock: RowCell[];
  middleBlock: RowCell[];
  rightBlock: RowCell[];
}

export function hasLeftBlock(row: number): boolean {
  return row >= 11;
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function couchIds(row: number, columnStart: number): [string, string] {
  return [seatId(row, columnStart), seatId(row, columnStart + 1)];
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat id: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessible(row: number, column: number): boolean {
  return row === ACCESSIBLE_ROW && column >= 10 && column <= 15;
}

export function priceForRow(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  return 39;
}

export function getRowLayout(row: number): RowLayout {
  if (row === COUCH_ROW) {
    const couches: CouchCell[] = [];
    for (let c = 1; c <= COLUMN_COUNT; c += 2) {
      couches.push({ kind: 'couch', columnStart: c, columnEnd: c + 1 });
    }
    return {
      row,
      leftBlock: couches.filter((c) => c.columnStart <= 4),
      middleBlock: couches.filter((c) => c.columnStart >= 5 && c.columnEnd <= 20),
      rightBlock: couches.filter((c) => c.columnStart >= 21),
    };
  }

  const leftBlock: SeatCell[] = hasLeftBlock(row) ? [1, 2, 3, 4].map((column) => ({ kind: 'seat', column })) : [];
  const middleBlock: SeatCell[] = [];
  for (let c = 5; c <= 20; c++) middleBlock.push({ kind: 'seat', column: c });
  const rightBlock: SeatCell[] = [21, 22, 23, 24].map((column) => ({ kind: 'seat', column }));

  return { row, leftBlock, middleBlock, rightBlock };
}

/** Toggles a single (non-couch) seat. Returns null when selecting it would exceed the cap. */
export function toggleSeatSelection(selected: string[], id: string): string[] | null {
  if (selected.includes(id)) {
    return selected.filter((s) => s !== id);
  }
  if (selected.length + 1 > MAX_SEATS_PER_BOOKING) {
    return null;
  }
  return [...selected, id];
}

/** Toggles a couch (its two identifiers) as one unit. Returns null when selecting it would exceed the cap. */
export function toggleCouchSelection(selected: string[], ids: [string, string]): string[] | null {
  const bothSelected = ids.every((id) => selected.includes(id));
  if (bothSelected) {
    return selected.filter((s) => !ids.includes(s));
  }
  if (selected.length + 2 > MAX_SEATS_PER_BOOKING) {
    return null;
  }
  return [...selected, ...ids];
}

export interface BookingItem {
  row: number;
  kind: 'seat' | 'couch';
  column?: number;
  columnStart?: number;
  columnEnd?: number;
  ids: string[];
  price: number;
}

/** Groups the flat seat-identifier selection into display/summary items, ordered by row then column. */
export function buildBookingItems(selectedIds: string[]): BookingItem[] {
  const byRow = new Map<number, number[]>();
  for (const id of selectedIds) {
    const { row, column } = parseSeatId(id);
    if (!byRow.has(row)) byRow.set(row, []);
    byRow.get(row)?.push(column);
  }

  const items: BookingItem[] = [];
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  for (const row of rows) {
    const columns = (byRow.get(row) ?? []).slice().sort((a, b) => a - b);
    if (row === COUCH_ROW) {
      for (let i = 0; i < columns.length; i += 2) {
        const a = columns[i];
        const b = columns[i + 1];
        items.push({
          row,
          kind: 'couch',
          columnStart: a,
          columnEnd: b,
          ids: [seatId(row, a), seatId(row, b)],
          price: COUCH_PRICE,
        });
      }
    } else {
      for (const column of columns) {
        items.push({
          row,
          kind: 'seat',
          column,
          ids: [seatId(row, column)],
          price: priceForRow(row),
        });
      }
    }
  }
  return items;
}

export function summarizeByRow(items: BookingItem[]): Array<{ row: number; label: string }> {
  const byRow = new Map<number, string[]>();
  for (const item of items) {
    const label = item.kind === 'couch' ? `${item.columnStart}-${item.columnEnd}` : `${item.column}`;
    if (!byRow.has(item.row)) byRow.set(item.row, []);
    byRow.get(item.row)?.push(label);
  }
  return [...byRow.keys()]
    .sort((a, b) => a - b)
    .map((row) => ({ row, label: (byRow.get(row) ?? []).join(', ') }));
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export interface CheckoutForm {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: CheckoutForm;
  paid: boolean;
  email?: string;
}

const STORAGE_KEY = 'cinescope:booking';

export const emptyCheckoutForm: CheckoutForm = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  terms: false,
};

export function createBooking(screeningId: number): Booking {
  return { screeningId, seats: [], form: { ...emptyCheckoutForm }, paid: false };
}

export function loadBooking(): Booking | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as Booking;
  } catch {
    return null;
  }
}

export function saveBooking(booking: Booking): void {
  sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
}

export function clearStoredBooking(): void {
  sessionStorage.removeItem(STORAGE_KEY);
}

import { createContext, ReactNode, useCallback, useContext, useState } from 'react';
import { Booking, clearStoredBooking, loadBooking, saveBooking } from '../lib/booking';

interface BookingContextValue {
  booking: Booking | null;
  setBooking: (booking: Booking) => void;
  updateBooking: (updater: (booking: Booking) => Booking) => void;
  clearBooking: () => void;
}

const BookingContext = createContext<BookingContextValue | null>(null);

export function BookingProvider({ children }: { children: ReactNode }) {
  const [booking, setBookingState] = useState<Booking | null>(() => loadBooking());

  const setBooking = useCallback((next: Booking) => {
    setBookingState(next);
    saveBooking(next);
  }, []);

  const updateBooking = useCallback((updater: (booking: Booking) => Booking) => {
    setBookingState((prev) => {
      if (!prev) return prev;
      const next = updater(prev);
      saveBooking(next);
      return next;
    });
  }, []);

  const clearBooking = useCallback(() => {
    setBookingState(null);
    clearStoredBooking();
  }, []);

  return (
    <BookingContext.Provider value={{ booking, setBooking, updateBooking, clearBooking }}>
      {children}
    </BookingContext.Provider>
  );
}

export function useBooking(): BookingContextValue {
  const ctx = useContext(BookingContext);
  if (!ctx) {
    throw new Error('useBooking must be used within a BookingProvider');
  }
  return ctx;
}

import Alert from '@mui/material/Alert';
import Snackbar from '@mui/material/Snackbar';
import { createContext, ReactNode, useCallback, useContext, useEffect, useRef, useState } from 'react';

interface ToastContextValue {
  showToast: (message: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

const TOAST_DURATION_MS = 4000;

export function ToastProvider({ children }: { children: ReactNode }) {
  const [message, setMessage] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const showToast = useCallback((next: string) => {
    if (timerRef.current) clearTimeout(timerRef.current);
    setMessage(next);
    timerRef.current = setTimeout(() => setMessage(null), TOAST_DURATION_MS);
  }, []);

  useEffect(
    () => () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    },
    [],
  );

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      <Snackbar open={message !== null} anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}>
        <Alert data-testid="toast" severity="info" variant="filled" sx={{ width: '100%' }}>
          {message}
        </Alert>
      </Snackbar>
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return ctx;
}

import { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useBooking } from '../context/BookingContext';

/**
 * Guards routes 3 and 4 (summary, checkout): the booking must be unpaid, belong to this
 * screening and hold at least one seat. Runs once per mount (route entry), not on every
 * booking change, so in-screen updates (e.g. removing the last summary item) are not
 * redirected by this guard.
 */
export function useUnpaidBookingGuard(screeningId: number): void {
  const { booking } = useBooking();
  const navigate = useNavigate();
  const checkedRef = useRef(false);

  useEffect(() => {
    if (checkedRef.current) return;
    checkedRef.current = true;
    const ok = !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
    if (!ok) {
      navigate('/', { replace: true });
    }
    // Intentionally only re-checks when the screening id changes, not on every booking update.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId]);
}

/** Guards route 5 (confirmation): the booking must be paid. */
export function usePaidBookingGuard(): void {
  const { booking } = useBooking();
  const navigate = useNavigate();
  const checkedRef = useRef(false);

  useEffect(() => {
    if (checkedRef.current) return;
    checkedRef.current = true;
    if (!booking?.paid) {
      navigate('/', { replace: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs, { Dayjs } from 'dayjs';
import { ISO_FORMAT, nextDays, weekdayFull } from '../../lib/dates';

const QUICK_DAY_COUNT = 5;

interface DayPickerProps {
  selectedDate: string;
  onSelect: (iso: string) => void;
}

export function DayPicker({ selectedDate, onSelect }: DayPickerProps) {
  const days = nextDays(QUICK_DAY_COUNT);
  const isQuickDay = days.includes(selectedDate);

  return (
    <Stack data-testid="day-picker" direction="row" spacing={1.5} alignItems="center" flexWrap="wrap">
      {days.map((date, index) => {
        const selected = date === selectedDate;
        const label = index === 0 ? 'Today' : weekdayFull(date);
        return (
          <Button
            key={date}
            data-testid="day-button"
            data-date={date}
            data-selected={selected ? 'true' : 'false'}
            variant={selected ? 'contained' : 'outlined'}
            onClick={() => onSelect(date)}
          >
            {label}
          </Button>
        );
      })}
      <DatePicker
        disablePast
        value={isQuickDay ? null : dayjs(selectedDate, ISO_FORMAT)}
        onChange={(value: Dayjs | null) => {
          if (value && value.isValid()) {
            onSelect(value.format(ISO_FORMAT));
          }
        }}
        slotProps={{ textField: { 'data-testid': 'date-picker', size: 'small' } }}
      />
    </Stack>
  );
}

import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { getMovies, getScreenings } from '../../lib/api';
import { resolveSelectedDate } from '../../lib/dates';
import { Movie, Screening } from '../../lib/types';
import { DayPicker } from './DayPicker';

type LoadState =
  | { status: 'loading' }
  | { status: 'error' }
  | { status: 'loaded'; movies: Movie[]; screenings: Screening[] };

export function MovieList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const selectedDate = resolveSelectedDate(searchParams.get('date'));
  const [state, setState] = useState<LoadState>({ status: 'loading' });

  const load = useCallback(() => {
    setState({ status: 'loading' });
    Promise.all([getMovies(), getScreenings({ date: selectedDate })])
      .then(([movies, screenings]) => setState({ status: 'loaded', movies, screenings }))
      .catch(() => setState({ status: 'error' }));
  }, [selectedDate]);

  useEffect(() => {
    load();
  }, [load]);

  const handleSelectDate = (date: string) => {
    setSearchParams({ date });
  };

  const cards = useMemo(() => {
    if (state.status !== 'loaded') return [];
    return state.movies
      .map((movie) => ({
        movie,
        screenings: state.screenings
          .filter((s) => s.movieId === movie.id)
          .slice()
          .sort((a, b) => a.time.localeCompare(b.time)),
      }))
      .filter((entry) => entry.screenings.length > 0);
  }, [state]);

  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', p: 3 }}>
      <DayPicker selectedDate={selectedDate} onSelect={handleSelectDate} />

      <Box sx={{ mt: 3 }}>
        {state.status === 'loading' && <Typography data-testid="movies-loading">Loading&hellip;</Typography>}

        {state.status === 'error' && (
          <Box data-testid="movies-error">
            <Typography sx={{ mb: 1 }}>Failed to load movies</Typography>
            <Button data-testid="movies-retry-button" variant="contained" onClick={load}>
              Retry
            </Button>
          </Box>
        )}

        {state.status === 'loaded' && cards.length === 0 && (
          <Typography data-testid="movies-empty">No screenings on this day</Typography>
        )}

        {state.status === 'loaded' && cards.length > 0 && (
          <Box data-testid="movie-list" sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {cards.map(({ movie, screenings }) => (
              <Box
                key={movie.id}
                data-testid="movie-card"
                data-movie-id={movie.id}
                sx={{ border: '1px solid #ccc', borderRadius: 1, p: 2 }}
              >
                <Typography data-testid="movie-title" variant="h6">
                  {movie.title}
                </Typography>
                <Typography data-testid="movie-genre">{movie.genre}</Typography>
                <Typography data-testid="movie-runtime">{movie.runtimeMinutes} min</Typography>
                <Typography data-testid="movie-format">{movie.format}</Typography>
                <Box sx={{ display: 'flex', gap: 1, mt: 1, flexWrap: 'wrap' }}>
                  {screenings.map((screening) => (
                    <Button
                      key={screening.id}
                      data-testid="screening-button"
                      data-screening-id={screening.id}
                      variant="outlined"
                      onClick={() => navigate(`/screenings/${screening.id}/seats`)}
                    >
                      {screening.time}
                    </Button>
                  ))}
                </Box>
              </Box>
            ))}
          </Box>
        )}
      </Box>
    </Box>
  );
}

