1	import Box from '@mui/material/Box';
2	import Button from '@mui/material/Button';
3	import Typography from '@mui/material/Typography';
4	import { useEffect, useMemo, useRef, useState } from 'react';
5	import { useNavigate, useParams } from 'react-router-dom';
6	import { useBooking } from '../../context/BookingContext';
7	import { useToast } from '../../context/ToastContext';
8	import { getMovie, getScreening } from '../../lib/api';
9	import { createBooking } from '../../lib/booking';
10	import { formatShowDate } from '../../lib/dates';
11	import { MAX_SEATS_PER_BOOKING, toggleCouchSelection, toggleSeatSelection } from '../../lib/seats';
12	import { Movie, Screening } from '../../lib/types';
13	import { Auditorium } from './Auditorium';
14	import { Legend } from './Legend';
15	import { SelectedSeatsPanel } from './SelectedSeatsPanel';
