1	import Box from '@mui/material/Box';
2	import Button from '@mui/material/Button';
3	import Typography from '@mui/material/Typography';
4	import { useEffect, useMemo, useRef, useState } from 'react';
5	import { useNavigate, useParams } from 'react-router-dom';
6	import { useBooking } from '../../context/BookingContext';
7	import { useToast } from '../../context/ToastContext';
8	import { getMovie, getScreening } from '../../lib/api';
9	import { createBooking } from '../../lib/booking';
10	import { formatShowDate } from '../../lib/dates';
11	import { MAX_SEATS_PER_BOOKING, toggleCouchSelection, toggleSeatSelection } from '../../lib/seats';
12	import { Movie, Screening } from '../../lib/types';
13	import { Auditorium } from './Auditorium';
14	import { Legend } from './Legend';
15	import { SelectedSeatsPanel } from './SelectedSeatsPanel';
16	
17	export function SeatMap() {
18	  const { id } = useParams<{ id: string }>();
19	  const screeningId = Number(id);
20	  const navigate = useNavigate();
21	  const { booking, setBooking, updateBooking, clearBooking } = useBooking();
22	  const { showToast } = useToast();
23	
24	  const [screening, setScreening] = useState<Screening | null>(null);
25	  const [movie, setMovie] = useState<Movie | null>(null);
26	  const initializedForRef = useRef<number | null>(null);
27	
28	  useEffect(() => {
29	    let cancelled = false;
30	    setScreening(null);
31	    setMovie(null);
32	    getScreening(screeningId)
33	      .then((loadedScreening) =>
34	        getMovie(loadedScreening.movieId).then((loadedMovie) => {
35	          if (cancelled) return;
36	          setScreening(loadedScreening);
37	          setMovie(loadedMovie);
38	        }),
39	      )
40	      .catch(() => {
41	        if (!cancelled) navigate('/', { replace: true });
42	      });
43	    return () => {
44	      cancelled = true;
45	    };
46	  }, [screeningId, navigate]);
47	
48	  useEffect(() => {
49	    if (!screening) return;
50	    if (initializedForRef.current === screening.id) return;
51	    initializedForRef.current = screening.id;
52	    const matches = booking && !booking.paid && booking.screeningId === screening.id;
53	    if (!matches) {
54	      setBooking(createBooking(screening.id));
55	    }
56	    // eslint-disable-next-line react-hooks/exhaustive-deps
57	  }, [screening]);
58	
59	  const occupiedSeats = useMemo(() => new Set(screening?.occupiedSeats ?? []), [screening]);
60	  const selectedSeats = useMemo(
61	    () => new Set(booking && booking.screeningId === screeningId ? booking.seats : []),
62	    [booking, screeningId],
63	  );
64	
65	  const ready = screening && movie && booking && booking.screeningId === screeningId && initializedForRef.current === screening.id;
66	
67	  if (!ready || !screening || !movie) {
68	    return null;
69	  }
70	
71	  const handleSeatClick = (seatId: string) => {
72	    const result = toggleSeatSelection(booking!.seats, seatId);
73	    if (result === null) {
74	      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
75	      return;
76	    }
77	    updateBooking((b) => ({ ...b, seats: result }));
78	  };
79	
80	  const handleCouchClick = (ids: [string, string]) => {
81	    const result = toggleCouchSelection(booking!.seats, ids);
82	    if (result === null) {
83	      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
84	      return;
85	    }
86	    updateBooking((b) => ({ ...b, seats: result }));
87	  };
88	
89	  const handleCancel = () => {
90	    clearBooking();
91	    navigate('/');
92	  };
93	
94	  const handleContinue = () => {
95	    if (booking!.seats.length === 0) return;
96	    navigate(`/screenings/${screening.id}/summary`);
97	  };
98	
99	  return (
100	    <Box sx={{ maxWidth: 1100, mx: 'auto', p: 3 }}>
101	      <Typography data-testid="seat-map-title" variant="h4" align="center" sx={{ mb: 1 }}>
102	        Choose your seats
103	      </Typography>
104	      <Typography data-testid="seat-map-subtitle" align="center" sx={{ mb: 2 }}>
105	        Show Date: {formatShowDate(screening.date, screening.time)}
106	      </Typography>
107	      <Typography data-testid="seat-limit-info" align="center" sx={{ mb: 3 }}>
108	        You can reserve up to {MAX_SEATS_PER_BOOKING} seats per reservation
109	      </Typography>
110	
111	      <Auditorium
112	        occupiedSeats={occupiedSeats}
113	        selectedSeats={selectedSeats}
114	        onSeatClick={handleSeatClick}
115	        onCouchClick={handleCouchClick}
116	      />
117	
118	      <Legend />
119	
120	      <SelectedSeatsPanel selectedIds={booking!.seats} />
121	
122	      <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2, mt: 3 }}>
123	        <Button data-testid="cancel-button" variant="outlined" onClick={handleCancel}>
124	          Cancel
125	        </Button>
126	        <Button
127	          data-testid="continue-button"
128	          variant="contained"
129	          disabled={booking!.seats.length === 0}
130	          onClick={handleContinue}
131	        >
132	          Continue
133	        </Button>
134	      </Box>
135	    </Box>
136	  );
137	}
