1	export const ROW_COUNT = 15;
2	export const COLUMN_COUNT = 24;
3	export const COUCH_ROW = 15;
4	export const ACCESSIBLE_ROW = 1;
5	export const ACCESSIBLE_COLUMNS = [10, 11, 12, 13, 14, 15];
6	export const MAX_SEATS_PER_BOOKING = 10;
7	export const COUCH_PRICE = 89;
8	
9	export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';
10	
11	export type SeatCell = { kind: 'seat'; column: number };
12	export type CouchCell = { kind: 'couch'; columnStart: number; columnEnd: number };
13	export type RowCell = SeatCell | CouchCell;
14	
15	export interface RowLayout {
16	  row: number;
17	  leftBlock: RowCell[];
18	  middleBlock: RowCell[];
19	  rightBlock: RowCell[];
20	}
21	
22	export function hasLeftBlock(row: number): boolean {
23	  return row >= 11;
24	}
25	
26	export function seatId(row: number, column: number): string {
27	  return `R${row}C${column}`;
28	}
29	
30	export function couchIds(row: number, columnStart: number): [string, string] {
31	  return [seatId(row, columnStart), seatId(row, columnStart + 1)];
32	}
33	
34	export function parseSeatId(id: string): { row: number; column: number } {
35	  const match = /^R(\d+)C(\d+)$/.exec(id);
36	  if (!match) {
37	    throw new Error(`Invalid seat id: ${id}`);
38	  }
39	  return { row: Number(match[1]), column: Number(match[2]) };
40	}
41	
42	export function isAccessible(row: number, column: number): boolean {
43	  return row === ACCESSIBLE_ROW && column >= 10 && column <= 15;
44	}
45	
46	export function getSeatState(id: string, row: number, column: number, occupied: Set<string>, selected: Set<string>): SeatState {
47	  if (selected.has(id)) return 'selected';
48	  if (occupied.has(id)) return 'unavailable';
49	  if (isAccessible(row, column)) return 'accessible';
50	  return 'available';
51	}
52	
53	export function getCouchState(ids: [string, string], occupied: Set<string>, selected: Set<string>): SeatState {
54	  if (ids.every((id) => selected.has(id))) return 'selected';
55	  if (ids.some((id) => occupied.has(id))) return 'unavailable';
56	  return 'available';
57	}
58	
59	export function priceForRow(row: number): number {
60	  if (row <= 5) return 25;
61	  if (row <= 10) return 32;
62	  return 39;
63	}
64	
65	export function getRowLayout(row: number): RowLayout {
66	  if (row === COUCH_ROW) {
67	    const couches: CouchCell[] = [];
68	    for (let c = 1; c <= COLUMN_COUNT; c += 2) {
69	      couches.push({ kind: 'couch', columnStart: c, columnEnd: c + 1 });
70	    }
71	    return {
72	      row,
73	      leftBlock: couches.filter((c) => c.columnStart <= 4),
74	      middleBlock: couches.filter((c) => c.columnStart >= 5 && c.columnEnd <= 20),
75	      rightBlock: couches.filter((c) => c.columnStart >= 21),
76	    };
77	  }
78	
79	  const leftBlock: SeatCell[] = hasLeftBlock(row) ? [1, 2, 3, 4].map((column) => ({ kind: 'seat', column })) : [];
80	  const middleBlock: SeatCell[] = [];
81	  for (let c = 5; c <= 20; c++) middleBlock.push({ kind: 'seat', column: c });
82	  const rightBlock: SeatCell[] = [21, 22, 23, 24].map((column) => ({ kind: 'seat', column }));
83	
84	  return { row, leftBlock, middleBlock, rightBlock };
85	}
86	
87	/** Toggles a single (non-couch) seat. Returns null when selecting it would exceed the cap. */
88	export function toggleSeatSelection(selected: string[], id: string): string[] | null {
89	  if (selected.includes(id)) {
90	    return selected.filter((s) => s !== id);
91	  }
92	  if (selected.length + 1 > MAX_SEATS_PER_BOOKING) {
93	    return null;
94	  }
95	  return [...selected, id];
96	}
97	
98	/** Toggles a couch (its two identifiers) as one unit. Returns null when selecting it would exceed the cap. */
99	export function toggleCouchSelection(selected: string[], ids: [string, string]): string[] | null {
100	  const bothSelected = ids.every((id) => selected.includes(id));
101	  if (bothSelected) {
102	    return selected.filter((s) => !ids.includes(s));
103	  }
104	  if (selected.length + 2 > MAX_SEATS_PER_BOOKING) {
105	    return null;
106	  }
107	  return [...selected, ...ids];
108	}
109	
110	export interface BookingItem {
111	  row: number;
112	  kind: 'seat' | 'couch';
113	  column?: number;
114	  columnStart?: number;
115	  columnEnd?: number;
116	  ids: string[];
117	  price: number;
118	}
119	
120	/** Groups the flat seat-identifier selection into display/summary items, ordered by row then column. */
121	export function buildBookingItems(selectedIds: string[]): BookingItem[] {
122	  const byRow = new Map<number, number[]>();
123	  for (const id of selectedIds) {
124	    const { row, column } = parseSeatId(id);
125	    if (!byRow.has(row)) byRow.set(row, []);
126	    byRow.get(row)?.push(column);
127	  }
128	
129	  const items: BookingItem[] = [];
130	  const rows = [...byRow.keys()].sort((a, b) => a - b);
131	  for (const row of rows) {
132	    const columns = (byRow.get(row) ?? []).slice().sort((a, b) => a - b);
133	    if (row === COUCH_ROW) {
134	      for (let i = 0; i < columns.length; i += 2) {
135	        const a = columns[i];
136	        const b = columns[i + 1];
137	        items.push({
138	          row,
139	          kind: 'couch',
140	          columnStart: a,
141	          columnEnd: b,
142	          ids: [seatId(row, a), seatId(row, b)],
143	          price: COUCH_PRICE,
144	        });
145	      }
146	    } else {
147	      for (const column of columns) {
148	        items.push({
149	          row,
150	          kind: 'seat',
151	          column,
152	          ids: [seatId(row, column)],
153	          price: priceForRow(row),
154	        });
155	      }
156	    }
157	  }
158	  return items;
159	}
160	
161	export function summarizeByRow(items: BookingItem[]): Array<{ row: number; label: string }> {
162	  const byRow = new Map<number, string[]>();
163	  for (const item of items) {
164	    const label = item.kind === 'couch' ? `${item.columnStart}-${item.columnEnd}` : `${item.column}`;
165	    if (!byRow.has(item.row)) byRow.set(item.row, []);
166	    byRow.get(item.row)?.push(label);
167	  }
168	  return [...byRow.keys()]
169	    .sort((a, b) => a - b)
170	    .map((row) => ({ row, label: (byRow.get(row) ?? []).join(', ') }));
171	}
172	
173	export function formatPrice(amount: number): string {
174	  return `${amount.toFixed(2)} PLN`;
175	}
