    await page.waitForTimeout(500);
    const bodyText = await page.textContent('body');
    report('page loaded', !!bodyText);

    const emptyVisible = await page.locator('[data-testid="movies-empty"]').count();
    const movieCards = await page.locator('[data-testid="movie-card"]').count();
    report('movie list rendered (empty or cards)', emptyVisible > 0 || movieCards > 0, `empty=${emptyVisible} cards=${movieCards}`);

    if (movieCards === 0) {
      // Today's date likely has no screenings (fixture data is Sept 2026). Navigate to a known date with screenings.
      await page.goto(`${BASE}/?date=2026-09-15`, { waitUntil: 'networkidle' });
      await page.waitForTimeout(500);
    }

    const cardsAfter = await page.locator('[data-testid="movie-card"]').count();
    report('movie cards present on 2026-09-15', cardsAfter > 0, `count=${cardsAfter}`);

    // Click first screening button
    const screeningBtn = page.locator('[data-testid="screening-button"]').first();
    const screeningCount = await page.locator('[data-testid="screening-button"]').count();
    report('screening buttons present', screeningCount > 0, `count=${screeningCount}`);
    await screeningBtn.click();
    await page.waitForURL(/\/screenings\/\d+\/seats/);
    report('navigated to seat map', true, page.url());

    await page.waitForTimeout(300);
    const seatMapTitle = await page.locator('[data-testid="seat-map-title"]').count();
    report('seat-map-title visible', seatMapTitle === 1);

    const availableSeats = page.locator('[data-testid="seat"][data-state="available"]');
    const availCount = await availableSeats.count();
    report('available seats found', availCount > 0, `count=${availCount}`);

    // select 2 seats
    await availableSeats.nth(0).click();
    await availableSeats.nth(1).click();
    const selectedCountText = await page.locator('[data-testid="selected-seats-count"]').textContent();
    report('selected-seats-count updates', selectedCountText?.includes('2'), selectedCountText ?? '');

    const continueBtn = page.locator('[data-testid="continue-button"]');
    report('continue button enabled', await continueBtn.isEnabled());
    await continueBtn.click();
    await page.waitForURL(/\/screenings\/\d+\/summary/);
    report('navigated to summary', true, page.url());

    await page.waitForTimeout(300);
    const summaryItems = await page.locator('[data-testid="summary-item"]').count();
    report('summary items shown', summaryItems > 0, `count=${summaryItems}`);
    const totalText = await page.locator('[data-testid="summary-total"]').textContent();
    report('summary total shown', !!totalText, totalText ?? '');

    await page.locator('[data-testid="confirm-button"]').click();
    await page.waitForURL(/\/screenings\/\d+\/checkout/);
    report('navigated to checkout', true, page.url());

    await page.waitForTimeout(300);
    // Try paying with empty form -> should show errors / toast
    await page.locator('[data-testid="pay-button"]').click();
    await page.waitForTimeout(200);
    const toastVisible = await page.locator('[data-testid="toast"]').count();
    report('toast shown on invalid submit', toastVisible > 0, `count=${toastVisible}`);

    // Fill form properly
    await page.locator('[data-testid="first-name-input"] input, input[data-testid="first-name-input"]').first().fill('John').catch(() => {});
    // fallback: try generic selectors by testid directly if input nested
    const fillField = async (testid, value) => {
      const direct = page.locator(`input[data-testid="${testid}"]`);
      if (await direct.count()) {
        await direct.fill(value);
        return;
      }
      const nested = page.locator(`[data-testid="${testid}"] input`);
      if (await nested.count()) {
        await nested.fill(value);
        return;
      }
      throw new Error(`field not found: ${testid}`);
    };

    await fillField('first-name-input', 'John');
    await fillField('last-name-input', 'Doe');
    await fillField('email-input', 'john@example.com');
    await fillField('confirm-email-input', 'john@example.com');
    await fillField('phone-input', '123456789');

    const termsCheckbox = page.locator('input[data-testid="terms-checkbox"], [data-testid="terms-checkbox"] input');
    await termsCheckbox.first().check();

    await page.locator('[data-testid="pay-button"]').click();
    await page.waitForURL(/\/confirmation/, { timeout: 5000 });
    report('navigated to confirmation', true, page.url());

    await page.waitForTimeout(300);
    const confirmHeading = await page.locator('[data-testid="confirmation-heading"]').textContent();
    report('confirmation heading shown', !!confirmHeading, confirmHeading ?? '');
    const confirmMsg = await page.locator('[data-testid="confirmation-message"]').textContent();
    report('confirmation message shows email', confirmMsg?.includes('john@example.com'), confirmMsg ?? '');

    // Reload confirmation page - should still show (paid booking persisted in sessionStorage)
    await page.reload({ waitUntil: 'networkidle' });
    await page.waitForTimeout(300);
    const confirmHeadingAfterReload = await page.locator('[data-testid="confirmation-heading"]').count();
    report('confirmation survives reload', confirmHeadingAfterReload === 1);

    await page.locator('[data-testid="confirmation-continue-button"]').click();
    await page.waitForURL(BASE + '/');
    report('continue returns to home', true, page.url());
  } catch (err) {
    console.log('FATAL ERROR:', err.message);
  } finally {
    console.log('--- console logs ---');
    for (const l of logs) console.log(l);
    await browser.close();
  }
};

run();

