1	import { useEffect, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { useBooking } from '../context/BookingContext';
4	
5	/**
6	 * Guards routes 3 and 4 (summary, checkout): the booking must be unpaid, belong to this
7	 * screening and hold at least one seat. Runs once per mount (route entry), not on every
8	 * booking change, so in-screen updates (e.g. removing the last summary item) are not
9	 * redirected by this guard.
10	 */
11	export function useUnpaidBookingGuard(screeningId: number): void {
12	  const { booking } = useBooking();
13	  const navigate = useNavigate();
14	  const checkedRef = useRef(false);
15	
16	  useEffect(() => {
17	    if (checkedRef.current) return;
18	    checkedRef.current = true;
19	    const ok = !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
20	    if (!ok) {
21	      navigate('/', { replace: true });
22	    }
23	    // Intentionally only re-checks when the screening id changes, not on every booking update.
24	    // eslint-disable-next-line react-hooks/exhaustive-deps
25	  }, [screeningId]);
26	}
27	
28	/** Guards route 5 (confirmation): the booking must be paid. */
29	export function usePaidBookingGuard(): void {
30	  const { booking } = useBooking();
31	  const navigate = useNavigate();
32	  const checkedRef = useRef(false);
33	
34	  useEffect(() => {
35	    if (checkedRef.current) return;
36	    checkedRef.current = true;
37	    if (!booking?.paid) {
38	      navigate('/', { replace: true });
39	    }
40	    // eslint-disable-next-line react-hooks/exhaustive-deps
41	  }, []);
42	}
