1	import Box from '@mui/material/Box';
2	import Button from '@mui/material/Button';
3	import Typography from '@mui/material/Typography';
4	import { useEffect, useMemo, useRef, useState } from 'react';
5	import { useNavigate, useParams } from 'react-router-dom';
6	import { useBooking } from '../../context/BookingContext';
7	import { useToast } from '../../context/ToastContext';
8	import { getMovie, getScreening } from '../../lib/api';
9	import { createBooking } from '../../lib/booking';
10	import { formatShowDate } from '../../lib/dates';
11	import { MAX_SEATS_PER_BOOKING, toggleCouchSelection, toggleSeatSelection } from '../../lib/seats';
12	import { Movie, Screening } from '../../lib/types';
13	import { Auditorium } from './Auditorium';
14	import { Legend } from './Legend';
15	import { SelectedSeatsPanel } from './SelectedSeatsPanel';
16	
17	export function SeatMap() {
18	  const { id } = useParams<{ id: string }>();
19	  const screeningId = Number(id);
20	  const navigate = useNavigate();
21	  const { booking, setBooking, updateBooking, clearBooking } = useBooking();
22	  const { showToast } = useToast();
23	
24	  const [screening, setScreening] = useState<Screening | null>(null);
25	  const [movie, setMovie] = useState<Movie | null>(null);
26	  const initializedForRef = useRef<number | null>(null);
27	
28	  useEffect(() => {
29	    let cancelled = false;
30	    setScreening(null);
31	    setMovie(null);
32	    getScreening(screeningId)
33	      .then((loadedScreening) =>
34	        getMovie(loadedScreening.movieId).then((loadedMovie) => {
35	          if (cancelled) return;
36	          setScreening(loadedScreening);
37	          setMovie(loadedMovie);
38	        }),
39	      )
40	      .catch(() => {
41	        if (!cancelled) navigate('/', { replace: true });
42	      });
43	    return () => {
44	      cancelled = true;
45	    };
46	  }, [screeningId, navigate]);
47	
48	  useEffect(() => {
49	    if (!screening) return;
50	    if (initializedForRef.current === screening.id) return;
51	    initializedForRef.current = screening.id;
52	    const matches = booking && !booking.paid && booking.screeningId === screening.id;
53	    if (!matches) {
54	      setBooking(createBooking(screening.id));
55	    }
56	    // eslint-disable-next-line react-hooks/exhaustive-deps
57	  }, [screening]);
58	
59	  const occupiedSeats = useMemo(() => new Set(screening?.occupiedSeats ?? []), [screening]);
60	  const selectedSeats = useMemo(
61	    () => new Set(booking && booking.screeningId === screeningId ? booking.seats : []),
62	    [booking, screeningId],
63	  );
64	
65	  if (
66	    !screening ||
67	    !movie ||
68	    !booking ||
69	    booking.screeningId !== screeningId ||
70	    initializedForRef.current !== screening.id
71	  ) {
72	    return null;
73	  }
74	
75	  const handleSeatClick = (seatId: string) => {
76	    const result = toggleSeatSelection(booking.seats, seatId);
77	    if (result === null) {
78	      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
79	      return;
80	    }
81	    updateBooking((b) => ({ ...b, seats: result }));
82	  };
83	
84	  const handleCouchClick = (ids: [string, string]) => {
85	    const result = toggleCouchSelection(booking.seats, ids);
86	    if (result === null) {
87	      showToast(`Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`);
88	      return;
89	    }
90	    updateBooking((b) => ({ ...b, seats: result }));
91	  };
92	
93	  const handleCancel = () => {
94	    clearBooking();
95	    navigate('/');
96	  };
97	
98	  const handleContinue = () => {
99	    if (booking.seats.length === 0) return;
100	    navigate(`/screenings/${screening.id}/summary`);
101	  };
102	
103	  return (
104	    <Box sx={{ maxWidth: 1100, mx: 'auto', p: 3 }}>
105	      <Typography data-testid="seat-map-title" variant="h4" align="center" sx={{ mb: 1 }}>
106	        Choose your seats
107	      </Typography>
108	      <Typography data-testid="seat-map-subtitle" align="center" sx={{ mb: 2 }}>
109	        Show Date: {formatShowDate(screening.date, screening.time)}
110	      </Typography>
111	      <Typography data-testid="seat-limit-info" align="center" sx={{ mb: 3 }}>
112	        You can reserve up to {MAX_SEATS_PER_BOOKING} seats per reservation
113	      </Typography>
114	
115	      <Auditorium
116	        occupiedSeats={occupiedSeats}
117	        selectedSeats={selectedSeats}
118	        onSeatClick={handleSeatClick}
119	        onCouchClick={handleCouchClick}
120	      />
121	
122	      <Legend />
123	
124	      <SelectedSeatsPanel selectedIds={booking.seats} />
125	
126	      <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2, mt: 3 }}>
127	        <Button data-testid="cancel-button" variant="outlined" onClick={handleCancel}>
128	          Cancel
129	        </Button>
130	        <Button
131	          data-testid="continue-button"
132	          variant="contained"
133	          disabled={booking.seats.length === 0}
134	          onClick={handleContinue}
135	        >
136	          Continue
137	        </Button>
138	      </Box>
139	    </Box>
140	  );
141	}
142

content.text:
This session is being continued from a previous conversation that ran out of context. The summary below covers the earlier portion of the conversation.

Summary:
1. Primary Request and Intent:
   The user asked me to build the cinema seat-booking web application described in spec/README.md, as the React application already scaffolded in this Nx workspace (Nx project `cinescope` in apps/cinescope). The stack is described in spec/stack.md. Work is split into tickets in spec/tickets/ (01 through 07) which must be implemented in order. spec/README.md is stated to be the complete specification: I must not ask any questions, and where it is silent I should choose the simplest option that satisfies it. The task finishes only when every ticket is done and `pnpm nx build cinescope` succeeds. No other user messages were given — this is the single, complete initial instruction, and all work since has been autonomous implementation based on reading the spec and tickets.

2. Key Technical Concepts:
   - Nx 23 monorepo with React 19 + Vite + React Router 6 (BrowserRouter) + SCSS + Vitest + ESLint
   - MUI 9 (@mui/material 9.4.0, @mui/icons-material) and MUI X Date Pickers 9.14.0 with dayjs 1.11.23 adapter
   - json-server 0.17.4 backend serving db.json at http://localhost:3000 (GET /movies, /movies/:id, /screenings, /screenings?date=, /screenings?movieId=, /screenings/:id, POST /reservations)
   - sessionStorage-persisted "booking in progress" state machine with strict route-guard semantics (route 2 requires screening exists; routes 3/4 require unpaid booking matching screening id with ≥1 seat; route 5 requires paid booking) — guards run once per route entry, not on every state change
   - Auditorium geometry: 15 rows × 24 columns, two aisles (between cols 4/5 and 20/21), entrance gap (rows 1-10 missing cols 1-4, not an aisle), accessible seats (row 1, cols 10-15), couches (row 15, 12 couches of 2 columns each) — total 308 selectable elements
   - Exact data-testid contract (section 9 of spec) — names/attributes must match exactly, not be renamed/abbreviated, and must only exist conditionally per spec (e.g., `movies-loading` only while loading, `-error` elements only while shown)
   - Seat pricing by row band (25/32/39 PLN) and couch flat price (89 PLN)
   - Toast system: single toast at a time, 4-second display, replaced instantly by new toasts
   - Checkout validation rules: required/min-length/email regex/match/phone regex/terms-required, with "touched" (blur-based) display logic that is NOT persisted (resets on fresh mount) while the typed values ARE persisted in the booking
