1	import Box from '@mui/material/Box';
2	import Button from '@mui/material/Button';
3	import Typography from '@mui/material/Typography';
4	import { useEffect, useMemo, useState } from 'react';
5	import { useNavigate, useParams } from 'react-router-dom';
6	import { useBooking } from '../../context/BookingContext';
7	import { getMovie, getScreening } from '../../lib/api';
8	import { buildBookingItems, formatPrice } from '../../lib/seats';
9	import { Movie, Screening } from '../../lib/types';
10	import { useUnpaidBookingGuard } from '../../routes/useBookingGuard';
11	
12	export function Summary() {
13	  const { id } = useParams<{ id: string }>();
14	  const screeningId = Number(id);
15	  const navigate = useNavigate();
16	  const { booking, updateBooking } = useBooking();
17	
18	  useUnpaidBookingGuard(screeningId);
19	
20	  const [screening, setScreening] = useState<Screening | null>(null);
21	  const [movie, setMovie] = useState<Movie | null>(null);
22	
23	  useEffect(() => {
24	    let cancelled = false;
25	    getScreening(screeningId)
26	      .then((loadedScreening) =>
27	        getMovie(loadedScreening.movieId).then((loadedMovie) => {
28	          if (cancelled) return;
29	          setScreening(loadedScreening);
30	          setMovie(loadedMovie);
31	        }),
32	      )
33	      .catch(() => {
34	        if (!cancelled) navigate('/', { replace: true });
35	      });
36	    return () => {
37	      cancelled = true;
38	    };
39	  }, [screeningId, navigate]);
40	
41	  const items = useMemo(() => buildBookingItems(booking?.seats ?? []), [booking]);
42	  const total = items.reduce((sum, item) => sum + item.price, 0);
43	
44	  if (!screening || !movie || !booking) {
45	    return null;
46	  }
47	
48	  const handleRemove = (ids: string[]) => {
49	    const nextSeats = booking.seats.filter((seatId) => !ids.includes(seatId));
50	    updateBooking((b) => ({ ...b, seats: nextSeats }));
51	    if (nextSeats.length === 0) {
52	      navigate(`/screenings/${screeningId}/seats`);
53	    }
54	  };
55	
56	  return (
57	    <Box sx={{ maxWidth: 800, mx: 'auto', p: 3 }}>
58	      <Typography data-testid="summary-title" variant="h4" sx={{ mb: 3 }}>
59	        Your tickets
60	      </Typography>
61	
62	      <Box data-testid="summary-list" sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
63	        {items.map((item) => (
64	          <Box
65	            key={item.ids.join('-')}
66	            data-testid="summary-item"
67	            sx={{
68	              display: 'flex',
69	              alignItems: 'center',
70	              justifyContent: 'space-between',
71	              border: '1px solid #ccc',
72	              borderRadius: 1,
73	              p: 2,
74	            }}
75	          >
76	            <Box>
77	              <Typography data-testid="summary-item-title">{movie.title}</Typography>
78	              <Typography data-testid="summary-item-datetime">
79	                {screening.date} {screening.time}
80	              </Typography>
81	              <Typography data-testid="summary-item-row">{item.row}</Typography>
82	              <Typography data-testid="summary-item-seat">
83	                {item.kind === 'couch' ? `Couch ${item.columnStart}-${item.columnEnd}` : `${item.column}`}
84	              </Typography>
85	              <Typography data-testid="summary-item-price">{formatPrice(item.price)}</Typography>
86	            </Box>
87	            <Button data-testid="summary-item-remove-button" onClick={() => handleRemove(item.ids)}>
88	              Remove
89	            </Button>
90	          </Box>
91	        ))}
92	      </Box>
93	
94	      <Typography data-testid="summary-total" sx={{ mt: 2 }}>
95	        Total: {formatPrice(total)}
96	      </Typography>
97	
98	      <Box sx={{ display: 'flex', gap: 2, mt: 3 }}>
99	        <Button data-testid="back-button" variant="outlined" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
100	          Back
101	        </Button>
102	        <Button
103	          data-testid="confirm-button"
104	          variant="contained"
105	          onClick={() => navigate(`/screenings/${screeningId}/checkout`)}
106	        >
107	          Confirm
108	        </Button>
109	      </Box>
110	    </Box>
111	  );
112	}
